                    }
                }
            }
        }
        target-address NMS_HOST {
            address 10.1.58.2;
            address-mask 255.255.255.0;
            tag-list NMS;
            target-parameters TP1;
        }
        target-parameters TP1 {
            parameters {
                message-processing-model v3;
                security-model usm;
                security-level privacy;
                security-name R5_NMS;
            }
        }
        notify SEND_TRAPS {
